package com.asmj.marketplace.advertising;
import com.asmj.marketplace.audit.AuditService; import com.asmj.marketplace.model.*; import com.asmj.marketplace.product.*; import com.asmj.marketplace.repository.*; import com.asmj.marketplace.service.CloudinaryImageService;
import jakarta.servlet.http.HttpSession; import java.math.BigDecimal; import java.security.Principal; import java.time.*; import java.util.*;
import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class AdvertisingController {
 private final AdCampaignRepository campaigns; private final AdPlacementRepository placements; private final AdPackageRepository packages; private final AdvertisingSettingsRepository settings; private final AdEventRepository events; private final AdvertisingService service; private final UserAccountRepository users; private final ProductRepository products; private final CategoryRepository categories; private final CloudinaryImageService uploads; private final AuditService audit;
 public AdvertisingController(AdCampaignRepository c,AdPlacementRepository p,AdPackageRepository a,AdvertisingSettingsRepository s,AdEventRepository e,AdvertisingService v,UserAccountRepository u,ProductRepository pr,CategoryRepository cat,CloudinaryImageService up,AuditService au){campaigns=c;placements=p;packages=a;settings=s;events=e;service=v;users=u;products=pr;categories=cat;uploads=up;audit=au;}
 @GetMapping("/vendor/advertising") public String vendorHome(Principal principal,Model m){service.ensureDefaults();UserAccount u=user(principal);m.addAttribute("campaigns",campaigns.findByVendorUserIdOrderByCreatedAtDesc(u.getId()));m.addAttribute("products",products.findByVendorUserIdOrderByCreatedAtDesc(u.getId()).stream().filter(p->p.getStatus()==ProductStatus.ACTIVE).toList());m.addAttribute("categories",categories.findByActiveTrueOrderByNameAsc());List<AdCampaign> vendorCampaigns=campaigns.findByVendorUserIdOrderByCreatedAtDesc(u.getId());m.addAttribute("totalImpressions",vendorCampaigns.stream().mapToLong(AdCampaign::getImpressions).sum());m.addAttribute("totalClicks",vendorCampaigns.stream().mapToLong(AdCampaign::getClicks).sum());m.addAttribute("placements",placements.findByEnabledTrueOrderByNameAsc());m.addAttribute("packages",packages.findByEnabledTrueOrderByPlacementCodeAscDurationDaysAsc());m.addAttribute("adSettings",service.currentSettings());return "vendor/advertising";}
 @GetMapping("/vendor/advertising/new") public String createForm(Principal principal,Model m){service.ensureDefaults();m.addAttribute("placements",placements.findByEnabledTrueOrderByNameAsc());m.addAttribute("packages",packages.findByEnabledTrueOrderByPlacementCodeAscDurationDaysAsc());m.addAttribute("products",products.findByVendorUserIdOrderByCreatedAtDesc(user(principal).getId()).stream().filter(p->p.getStatus()==ProductStatus.ACTIVE).toList());m.addAttribute("categories",categories.findByActiveTrueOrderByNameAsc());m.addAttribute("minimumStartDate",LocalDate.now(ZoneId.of("Asia/Kolkata")));m.addAttribute("adSettings",service.currentSettings());return "advertising/create";}
 @PostMapping("/vendor/advertising/create") public String create(Principal principal,@RequestParam String placementCode,@RequestParam String packageId,@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) String callToAction,@RequestParam(required=false) String productId,@RequestParam(required=false) String categoryId,@RequestParam(required=false) String destinationUrl,@RequestParam String startDate,@RequestParam(required=false) String targetPinCodes,@RequestParam MultipartFile banner,@RequestParam(required=false) MultipartFile mobileBanner,RedirectAttributes ra){
  try{UserAccount u=user(principal);if(!service.currentSettings().isEnabled()||service.currentSettings().getUpiId()==null||service.currentSettings().getUpiId().isBlank())throw new IllegalArgumentException("Advertising is temporarily unavailable. Please contact ASMJ Shoppe admin.");AdPlacement p=placements.findByCode(placementCode).filter(AdPlacement::isEnabled).orElseThrow(()->new IllegalArgumentException("Choose an available advertising placement."));AdPackage pkg=packages.findByIdAndEnabledTrue(packageId).filter(x->placementCode.equals(x.getPlacementCode())).orElseThrow(()->new IllegalArgumentException("Choose a valid package for the selected placement."));if(title==null||title.trim().length()<4||title.trim().length()>90)throw new IllegalArgumentException("Advertisement title must contain 4–90 characters.");if(description!=null&&description.length()>240||callToAction!=null&&callToAction.length()>24)throw new IllegalArgumentException("Description is limited to 240 characters and call-to-action to 24 characters.");LocalDate start=LocalDate.parse(startDate);LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));if(start.isBefore(today)||start.isAfter(today.plusDays(90)))throw new IllegalArgumentException("Choose a campaign start date from today through the next 90 days.");String target=destinationUrl==null?"":destinationUrl.trim();if(productId!=null&&!productId.isBlank()){Product product=products.findById(productId).filter(x->u.getId().equals(x.getVendorUserId())&&x.getStatus()==ProductStatus.ACTIVE).orElseThrow(()->new IllegalArgumentException("Select one of your active products."));target="/products/"+product.getId();categoryId=product.getCategoryId();}if(categoryId!=null&&!categoryId.isBlank()){String selectedCategory=categoryId;categories.findById(selectedCategory).filter(Category::isActive).orElseThrow(()->new IllegalArgumentException("Choose an active marketplace category."));}if(target.isBlank()&&categoryId!=null&&!categoryId.isBlank())target="/products?categoryId="+categoryId;if(target.isBlank())target="/products";if(!target.matches("^/(?!/)[^\r\n]*$")||target.contains("..")||target.contains("\\"))throw new IllegalArgumentException("Choose one of your active products or a safe internal marketplace destination.");List<String> pins=parsePins(targetPinCodes);Map<String,Object> up=uploads.uploadAdvertisementBanner(banner);String mobileUrl=null;if(mobileBanner!=null&&!mobileBanner.isEmpty())mobileUrl=(String)uploads.uploadAdvertisementBanner(mobileBanner).get("secure_url");AdCampaign c=new AdCampaign();c.setVendorUserId(u.getId());c.setVendorName(u.getFullName());c.setPlacementCode(p.getCode());c.setPlacementName(p.getName());c.setTitle(title.trim());c.setDescription(description==null?"":description.trim());c.setCallToAction(callToAction==null||callToAction.isBlank()?"Shop now":callToAction.trim());c.setBannerUrl((String)up.get("secure_url"));c.setMobileBannerUrl(mobileUrl);c.setDestinationUrl(target);c.setProductId(productId);c.setCategoryId(categoryId);c.setTargetPinCodes(pins);c.setDurationDays(pkg.getDurationDays());c.setStartDate(start);c.setEndDate(start.plusDays(pkg.getDurationDays()-1L));c.setAmount(pkg.getPrice());c.setStatus("PENDING_PAYMENT");c.setPaymentStatus("PENDING");c.setApprovalStatus("PENDING");c.setCreatedAt(Instant.now());c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(u.getEmail(),"VENDOR","AD_CAMPAIGN_CREATED","AD_CAMPAIGN",c.getId(),"Campaign submitted for UPI payment and creative review.");ra.addFlashAttribute("successMessage","Campaign created. Complete UPI payment and submit your UTR and screenshot.");return "redirect:/vendor/advertising/"+c.getId()+"/payment";}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));return "redirect:/vendor/advertising/new";}}
 @GetMapping("/vendor/advertising/{id}/payment") public String payment(@PathVariable String id,Principal principal,Model m,RedirectAttributes ra){AdCampaign c=owned(id,principal);if(c==null){ra.addFlashAttribute("errorMessage","Campaign not found.");return "redirect:/vendor/advertising";}m.addAttribute("campaign",c);m.addAttribute("adSettings",service.currentSettings());return "advertising/payment";}
 @PostMapping("/vendor/advertising/{id}/payment") public String submitPayment(@PathVariable String id,Principal principal,@RequestParam String utr,@RequestParam MultipartFile proof,RedirectAttributes ra){try{AdCampaign c=owned(id,principal);if(c==null)throw new IllegalArgumentException("Campaign not found.");if(!List.of("PENDING","REJECTED").contains(c.getPaymentStatus()))throw new IllegalArgumentException("Payment evidence has already been submitted or verified.");if(utr==null||!utr.trim().matches("[A-Za-z0-9]{8,30}"))throw new IllegalArgumentException("Enter a valid UTR/reference of 8–30 letters or digits.");if(campaigns.existsByPaymentUtrIgnoreCaseAndIdNot(utr.trim(),id))throw new IllegalArgumentException("This UTR/reference has already been submitted for another advertising campaign.");Map<String,Object> uploaded=uploads.uploadDocument(proof,"asmj-marketplace/advertising/payment-proofs");c.setPaymentUtr(utr.trim());c.setPaymentProofUrl((String)uploaded.get("secure_url"));c.setPaymentProofName(proof.getOriginalFilename());c.setPaymentStatus("SUBMITTED");c.setStatus("PAYMENT_SUBMITTED");c.setPaymentNote("");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"VENDOR","AD_PAYMENT_SUBMITTED","AD_CAMPAIGN",id,"UPI proof submitted for verification.");ra.addFlashAttribute("successMessage","Payment proof submitted for admin verification.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/vendor/advertising";}
 @PostMapping("/vendor/advertising/{id}/creative-resubmit") public String resubmitCreative(@PathVariable String id,Principal principal,@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) String callToAction,@RequestParam(required=false) String productId,@RequestParam(required=false) String categoryId,@RequestParam(required=false) String destinationUrl,@RequestParam(required=false) String targetPinCodes,@RequestParam(required=false) MultipartFile banner,@RequestParam(required=false) MultipartFile mobileBanner,RedirectAttributes ra){try{AdCampaign c=owned(id,principal);if(c==null||!"REJECTED".equals(c.getApprovalStatus())||!"VERIFIED".equals(c.getPaymentStatus()))throw new IllegalArgumentException("This campaign is not eligible for creative resubmission.");if(title==null||title.trim().length()<4||title.trim().length()>90)throw new IllegalArgumentException("Advertisement title must contain 4–90 characters.");if(description!=null&&description.length()>240||callToAction!=null&&callToAction.length()>24)throw new IllegalArgumentException("Description is limited to 240 characters and call-to-action to 24 characters.");String target=destinationUrl==null?"":destinationUrl.trim();if(productId!=null&&!productId.isBlank()){Product product=products.findById(productId).filter(x->user(principal).getId().equals(x.getVendorUserId())&&x.getStatus()==ProductStatus.ACTIVE).orElseThrow(()->new IllegalArgumentException("Select one of your active products."));target="/products/"+product.getId();categoryId=product.getCategoryId();}if(categoryId!=null&&!categoryId.isBlank()){String selected=categoryId;categories.findById(selected).filter(Category::isActive).orElseThrow(()->new IllegalArgumentException("Choose an active marketplace category."));}if(target.isBlank()&&categoryId!=null&&!categoryId.isBlank())target="/products?categoryId="+categoryId;if(target.isBlank())target="/products";if(!target.matches("^/(?!/)[^\r\n]*$")||target.contains("..")||target.contains("\\"))throw new IllegalArgumentException("Use a safe internal marketplace destination.");List<String> pins=parsePins(targetPinCodes);if(banner!=null&&!banner.isEmpty())c.setBannerUrl((String)uploads.uploadAdvertisementBanner(banner).get("secure_url"));if(mobileBanner!=null&&!mobileBanner.isEmpty())c.setMobileBannerUrl((String)uploads.uploadAdvertisementBanner(mobileBanner).get("secure_url"));c.setTitle(title.trim());c.setDescription(description==null?"":description.trim());c.setCallToAction(callToAction==null||callToAction.isBlank()?"Shop now":callToAction.trim());c.setProductId(productId);c.setCategoryId(categoryId);c.setDestinationUrl(target);c.setTargetPinCodes(pins);c.setApprovalStatus("PENDING");c.setRejectionReason(null);c.setStatus("PAYMENT_VERIFIED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"VENDOR","AD_CREATIVE_RESUBMITTED","AD_CAMPAIGN",id,"Vendor resubmitted rejected creative without another payment.");ra.addFlashAttribute("successMessage","Updated creative submitted. Your verified payment remains attached to this campaign.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/vendor/advertising";}
 @GetMapping("/admin/advertising") public String admin(Principal principal,Model m){service.ensureDefaults();m.addAttribute("campaigns",campaigns.findAllByOrderByCreatedAtDesc());m.addAttribute("placements",placements.findAll());m.addAttribute("packages",packages.findAllByOrderByPlacementCodeAscDurationDaysAsc());m.addAttribute("adSettings",service.currentSettings());m.addAttribute("liveCampaigns",campaigns.findAll().stream().filter(c->c.isLive()&&placements.findByCode(c.getPlacementCode()).map(AdPlacement::isEnabled).orElse(false)).count());long impressions=campaigns.findAll().stream().mapToLong(AdCampaign::getImpressions).sum();long clicks=campaigns.findAll().stream().mapToLong(AdCampaign::getClicks).sum();m.addAttribute("totalImpressions",impressions);m.addAttribute("totalClicks",clicks);m.addAttribute("totalCtr",impressions>0?BigDecimal.valueOf(clicks*100.0/impressions).setScale(2,java.math.RoundingMode.HALF_UP):BigDecimal.ZERO);m.addAttribute("totalRevenue",campaigns.findAll().stream().filter(c->"VERIFIED".equals(c.getPaymentStatus())).map(AdCampaign::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add));return "admin/advertising";}
 @PostMapping("/admin/advertising/settings") public String saveSettings(@RequestParam String upiId,@RequestParam String payeeName,@RequestParam(required=false) String qrImageUrl,@RequestParam(required=false) MultipartFile qrImage,@RequestParam(defaultValue="false") boolean enabled,Principal principal,RedirectAttributes ra){if(upiId==null||!upiId.trim().matches("[A-Za-z0-9._-]{2,256}@[A-Za-z]{2,30}")||payeeName==null||payeeName.trim().isBlank()){ra.addFlashAttribute("errorMessage","Enter a valid UPI ID and payee name.");return "redirect:/admin/advertising";}try{AdvertisingSettings s=service.currentSettings();s.setUpiId(upiId.trim());s.setPayeeName(payeeName.trim());if(qrImage!=null&&!qrImage.isEmpty())s.setQrImageUrl((String)uploads.uploadAdvertisementBanner(qrImage).get("secure_url"));else if(qrImageUrl!=null&&!qrImageUrl.isBlank()){if(!qrImageUrl.startsWith("https://"))throw new IllegalArgumentException("QR image URL must use HTTPS.");s.setQrImageUrl(qrImageUrl.trim());}s.setEnabled(enabled);s.setUpdatedAt(Instant.now());settings.save(s);audit.record(user(principal).getEmail(),"ADMIN","AD_UPI_SETTINGS_UPDATED","AD_SETTINGS","default","Advertising UPI details updated.");ra.addFlashAttribute("successMessage","Advertising UPI settings saved.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/placements") public String savePlacement(@RequestParam(required=false) String id,@RequestParam String code,@RequestParam String name,@RequestParam(required=false) String description,@RequestParam(required=false) String desktopSize,@RequestParam(required=false) String mobileSize,@RequestParam int maxConcurrent,@RequestParam(defaultValue="false") boolean enabled,Principal principal,RedirectAttributes ra){try{if(!code.matches("[A-Z_]{3,40}")||maxConcurrent<1||maxConcurrent>20)throw new IllegalArgumentException("Placement code must use uppercase letters/underscores and capacity must be 1–20.");if(placements.findByCode(code).filter(existing->id==null||id.isBlank()||!existing.getId().equals(id)).isPresent())throw new IllegalArgumentException("That placement code is already in use.");AdPlacement p=id==null||id.isBlank()?placements.findByCode(code).orElseGet(AdPlacement::new):placements.findById(id).orElseThrow();if(p.getCode()!=null&&!p.getCode().equals(code)&&(packages.findAll().stream().anyMatch(x->x.getPlacementCode().equals(p.getCode()))||campaigns.findAll().stream().anyMatch(x->x.getPlacementCode().equals(p.getCode()))))throw new IllegalArgumentException("This placement code is already referenced by packages or campaigns. Create a new placement instead of renaming it.");p.setCode(code);p.setName(name.trim());p.setDescription(description);p.setDesktopSize(desktopSize);p.setMobileSize(mobileSize);p.setMaxConcurrent(maxConcurrent);p.setEnabled(enabled);p.setUpdatedAt(Instant.now());placements.save(p);audit.record(user(principal).getEmail(),"ADMIN","AD_PLACEMENT_SAVED","AD_PLACEMENT",p.getId(),p.getCode());ra.addFlashAttribute("successMessage","Placement saved.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/packages") public String savePackage(@RequestParam(required=false) String id,@RequestParam String placementCode,@RequestParam String name,@RequestParam int durationDays,@RequestParam BigDecimal price,@RequestParam(defaultValue="false") boolean enabled,Principal principal,RedirectAttributes ra){try{if(placements.findByCode(placementCode).isEmpty()||durationDays<1||durationDays>365||price==null||price.signum()<0||price.compareTo(new BigDecimal("1000000"))>0)throw new IllegalArgumentException("Select a placement, duration 1–365 days and price ₹0–₹10,00,000.");if(packages.findAll().stream().anyMatch(existing->!Objects.equals(existing.getId(),id)&&existing.getPlacementCode().equals(placementCode)&&existing.getDurationDays()==durationDays))throw new IllegalArgumentException("A package with this duration already exists for the selected placement.");AdPackage p=id==null||id.isBlank()?new AdPackage():packages.findById(id).orElseThrow();p.setPlacementCode(placementCode);p.setName(name.trim());p.setDurationDays(durationDays);p.setPrice(price.setScale(2,java.math.RoundingMode.HALF_UP));p.setEnabled(enabled);p.setUpdatedAt(Instant.now());packages.save(p);audit.record(user(principal).getEmail(),"ADMIN","AD_PACKAGE_SAVED","AD_PACKAGE",p.getId(),placementCode+" / "+durationDays+" days");ra.addFlashAttribute("successMessage","Advertising package saved.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/payment/verify") public String verifyPayment(@PathVariable String id,Principal principal,@RequestParam(defaultValue="") String note,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null||!"SUBMITTED".equals(c.getPaymentStatus())){ra.addFlashAttribute("errorMessage","No submitted payment is available to verify.");return "redirect:/admin/advertising";}c.setPaymentStatus("VERIFIED");c.setPaymentVerifiedBy(user(principal).getEmail());c.setPaymentVerifiedAt(Instant.now());c.setPaymentNote(note);c.setStatus("PAYMENT_VERIFIED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"ADMIN","AD_PAYMENT_VERIFIED","AD_CAMPAIGN",id,"UPI payment verified.");ra.addFlashAttribute("successMessage","Payment verified. Creative approval is still required.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/payment/reject") public String rejectPayment(@PathVariable String id,Principal principal,@RequestParam String reason,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null||!"SUBMITTED".equals(c.getPaymentStatus())||reason==null||reason.isBlank()){ra.addFlashAttribute("errorMessage","A submitted payment and rejection reason are required.");return "redirect:/admin/advertising";}c.setPaymentStatus("REJECTED");c.setPaymentNote(reason.trim());c.setStatus("PAYMENT_REJECTED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"ADMIN","AD_PAYMENT_REJECTED","AD_CAMPAIGN",id,reason);ra.addFlashAttribute("successMessage","Payment proof rejected. Vendor can resubmit.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/approve") public String approve(@PathVariable String id,Principal principal,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null||!"VERIFIED".equals(c.getPaymentStatus())||!"PENDING".equals(c.getApprovalStatus())||"SUSPENDED".equals(c.getStatus())){ra.addFlashAttribute("errorMessage","Verify payment and ensure the creative is pending and not suspended before approval.");return "redirect:/admin/advertising";}if(c.getStartDate()==null||c.getEndDate()==null||!c.getEndDate().isAfter(c.getStartDate().minusDays(1))){ra.addFlashAttribute("errorMessage","Campaign dates are invalid.");return "redirect:/admin/advertising";}AdPlacement p=placements.findByCode(c.getPlacementCode()).orElse(null);if(p==null||!p.isEnabled()){ra.addFlashAttribute("errorMessage","The selected placement is disabled.");return "redirect:/admin/advertising";}long overlap=campaigns.findAll().stream().filter(x->!x.getId().equals(id)&&x.getPlacementCode().equals(c.getPlacementCode())&&"APPROVED".equals(x.getApprovalStatus())&&"VERIFIED".equals(x.getPaymentStatus())&&!List.of("SUSPENDED","REJECTED","EXPIRED").contains(x.getStatus())&&x.getStartDate()!=null&&x.getEndDate()!=null&&!x.getEndDate().isBefore(c.getStartDate())&&!x.getStartDate().isAfter(c.getEndDate())).count();if(overlap>=p.getMaxConcurrent()){ra.addFlashAttribute("errorMessage","This placement has reached its concurrent campaign capacity for the selected dates.");return "redirect:/admin/advertising";}c.setApprovalStatus("APPROVED");c.setApprovedBy(user(principal).getEmail());c.setApprovedAt(Instant.now());c.setStatus("APPROVED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"ADMIN","AD_CREATIVE_APPROVED","AD_CAMPAIGN",id,"Advertisement approved and scheduled.");ra.addFlashAttribute("successMessage","Advertisement approved and scheduled.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/reject") public String reject(@PathVariable String id,Principal principal,@RequestParam String reason,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c==null||!"VERIFIED".equals(c.getPaymentStatus())||!"PENDING".equals(c.getApprovalStatus())||reason==null||reason.isBlank()){ra.addFlashAttribute("errorMessage","A pending, payment-verified creative and a rejection reason are required.");return "redirect:/admin/advertising";}c.setApprovalStatus("REJECTED");c.setRejectionReason(reason.trim());c.setStatus("REJECTED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"ADMIN","AD_CREATIVE_REJECTED","AD_CAMPAIGN",id,reason);ra.addFlashAttribute("successMessage","Advertisement rejected.");return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/refund") public String refund(@PathVariable String id,Principal principal,@RequestParam String refundReference,@RequestParam String refundNote,@RequestParam(required=false) MultipartFile refundProof,RedirectAttributes ra){try{AdCampaign c=campaigns.findById(id).orElseThrow(()->new IllegalArgumentException("Campaign not found."));if(!"VERIFIED".equals(c.getPaymentStatus())||"REFUNDED".equals(c.getRefundStatus()))throw new IllegalArgumentException("Only a paid, not-yet-refunded campaign can be refunded.");if(refundReference==null||!refundReference.trim().matches("[A-Za-z0-9]{8,30}")||refundNote==null||refundNote.trim().isBlank())throw new IllegalArgumentException("Enter the refund UTR/reference (8–30 characters) and reason.");if(campaigns.existsByRefundReferenceIgnoreCaseAndIdNot(refundReference.trim(),id))throw new IllegalArgumentException("This refund reference has already been recorded for another campaign.");String proofUrl=null;if(refundProof!=null&&!refundProof.isEmpty())proofUrl=(String)uploads.uploadDocument(refundProof,"asmj-marketplace/advertising/refunds").get("secure_url");c.setRefundStatus("REFUNDED");c.setRefundAmount(c.getAmount());c.setRefundReference(refundReference.trim());c.setRefundProofUrl(proofUrl);c.setRefundNote(refundNote.trim());c.setRefundedBy(user(principal).getEmail());c.setRefundedAt(Instant.now());c.setPaymentStatus("REFUNDED");c.setStatus("REFUNDED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"ADMIN","AD_CAMPAIGN_REFUNDED","AD_CAMPAIGN",id,"Full advertising campaign refund recorded by UPI.");ra.addFlashAttribute("successMessage","Full advertising refund recorded. Campaign is no longer eligible for display.");}catch(Exception ex){ra.addFlashAttribute("errorMessage",message(ex));}return "redirect:/admin/advertising";}
 @PostMapping("/admin/advertising/{id}/suspend") public String suspend(@PathVariable String id,Principal principal,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).orElse(null);if(c!=null){c.setStatus("SUSPENDED");c.setUpdatedAt(Instant.now());campaigns.save(c);audit.record(user(principal).getEmail(),"ADMIN","AD_CAMPAIGN_SUSPENDED","AD_CAMPAIGN",id,"Campaign suspended.");}ra.addFlashAttribute("successMessage","Campaign suspended.");return "redirect:/admin/advertising";}
 @GetMapping("/ads/target-pin") public String setTargetPin(@RequestParam(required=false) String pinCode,HttpSession session,RedirectAttributes ra){if(pinCode==null||!pinCode.matches("[0-9]{6}")){session.removeAttribute("asmjAdTargetPin");ra.addFlashAttribute("errorMessage","Enter a valid 6-digit PIN code to filter local promotions.");}else{session.setAttribute("asmjAdTargetPin",pinCode);ra.addFlashAttribute("successMessage","Promotions will be filtered for PIN code "+pinCode+".");}return "redirect:/products";}
 @GetMapping(value="/ads/impression/{id}",produces="image/gif") @ResponseBody public byte[] impression(@PathVariable String id,HttpSession session){recordEvent(id,"IMPRESSION",session.getId());return java.util.Base64.getDecoder().decode("R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=");}
 @GetMapping("/ads/click/{id}") public String click(@PathVariable String id,HttpSession session,RedirectAttributes ra){AdCampaign c=campaigns.findById(id).filter(this::isServable).orElse(null);if(c==null)return "redirect:/products";recordEvent(id,"CLICK",session.getId());String url=c.getDestinationUrl();if(url==null||!url.matches("^/(?!/)[^\r\n]*$")||url.contains("..")||url.contains("\\"))return "redirect:/products";return "redirect:"+url;}
 private void recordEvent(String id,String type,String visitor){visitor=hashVisitor(visitor);AdCampaign c=campaigns.findById(id).filter(this::isServable).orElse(null);if(c==null)return;LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));if(events.existsByCampaignIdAndEventTypeAndVisitorKeyAndEventDate(id,type,visitor,today))return;AdEvent e=new AdEvent();e.setCampaignId(id);e.setEventType(type);e.setVisitorKey(visitor);e.setEventDate(today);events.save(e);if("CLICK".equals(type))c.setClicks(c.getClicks()+1);else c.setImpressions(c.getImpressions()+1);campaigns.save(c);}
 private boolean isServable(AdCampaign c){return c.isLive()&&placements.findByCode(c.getPlacementCode()).map(AdPlacement::isEnabled).orElse(false);}
 private String hashVisitor(String value){try{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));return java.util.HexFormat.of().formatHex(bytes);}catch(Exception ex){return Integer.toHexString(value.hashCode());}}
 private List<String> parsePins(String raw){if(raw==null||raw.isBlank())return new ArrayList<>();LinkedHashSet<String> out=new LinkedHashSet<>();for(String x:raw.split("[,\\s]+")){if(!x.matches("[0-9]{6}"))throw new IllegalArgumentException("Target PIN codes must contain six digits each.");out.add(x);}if(out.size()>1000)throw new IllegalArgumentException("Maximum 1000 target PIN codes allowed.");return new ArrayList<>(out);}
 private UserAccount user(Principal p){return users.findByEmailIgnoreCase(p.getName()).orElseThrow();} private AdCampaign owned(String id,Principal p){return campaigns.findById(id).filter(c->c.getVendorUserId().equals(user(p).getId())).orElse(null);} private String message(Exception e){return e.getMessage()==null?"Unable to process advertising request.":e.getMessage();}
}
